package com.companages.repository; import com.companages.entity.Notification; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.Instant;
public interface NotificationRepository extends JpaRepository<Notification,Long>{Page<Notification> findByUserId(Long userId,Pageable pageable); long countByUserIdAndReadAtIsNull(Long userId); @Modifying @Query("update Notification n set n.readAt=:now where n.user.id=:userId and n.readAt is null") int markAllRead(@Param("userId")Long userId,@Param("now")Instant now);}
